import * as React from 'react';
import { expect, vi, it, describe, afterEach } from 'vitest';
import { render, fireEvent, screen, cleanup, act } from '@testing-library/react';
import { Field } from '@base-ui/react/field';
import { Form } from '@base-ui/react/form';

afterEach(cleanup);

describe('scratch', () => {
  it('A numeric dirty clears', () => {
    function App() {
      const [value, setValue] = React.useState(5);
      return (
        <Field.Root data-testid="root">
          <Field.Control value={value} onValueChange={(v) => setValue(Number(v))} />
        </Field.Root>
      );
    }
    render(<App />);
    const root = screen.getByTestId('root');
    const control = screen.getByRole('textbox');
    expect(root.hasAttribute('data-dirty')).toBe(false);
    fireEvent.change(control, { target: { value: '56' } });
    expect(root.hasAttribute('data-dirty')).toBe(true);
    fireEvent.change(control, { target: { value: '5' } });
    expect(root.hasAttribute('data-dirty')).toBe(false);
  });

  it('B programmatic sync', () => {
    const validate = vi.fn((_v: unknown) => null);
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
          <Field.Control value={value} onValueChange={setValue} />
          <button type="button" onClick={() => setValue('external')}>set</button>
        </Field.Root>
      );
    }
    render(<App />);
    fireEvent.click(screen.getByRole('button'));
    const root = screen.getByTestId('root');
    expect(root.hasAttribute('data-filled')).toBe(true);
    expect(root.hasAttribute('data-dirty')).toBe(true);
    expect(validate).toHaveBeenCalledTimes(1);
  });

  it('C cancel uncontrolled', () => {
    const validate = vi.fn(() => null);
    render(
      <Field.Root validationMode="onChange" validate={validate}>
        <Field.Control onValueChange={(_v, d) => d.cancel()} />
      </Field.Root>,
    );
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
    expect(validate).not.toHaveBeenCalled();
  });

  it('D validates once controlled', () => {
    const validate = vi.fn(() => null);
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root validationMode="onChange" validate={validate}>
          <Field.Control value={value} onValueChange={setValue} />
        </Field.Root>
      );
    }
    render(<App />);
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
    expect(validate).toHaveBeenCalledTimes(1);
  });

  it('E rejected controlled value does not reach field state', () => {
    const validate = vi.fn(() => null);
    render(
      <Field.Root data-testid="root" validationMode="onChange" validate={validate}>
        <Field.Control value="" onValueChange={() => {}} />
      </Field.Root>,
    );
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'a' } });
    const root = screen.getByTestId('root');
    expect(validate).not.toHaveBeenCalled();
    expect(root.hasAttribute('data-dirty')).toBe(false);
    expect(root.hasAttribute('data-filled')).toBe(false);
  });

  it('F programmatic change clears Form errors', () => {
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Form errors={{ message: 'Server error' }}>
          <Field.Root name="message">
            <Field.Control value={value} onValueChange={setValue} />
            <Field.Error />
          </Field.Root>
          <button type="button" onClick={() => setValue('external')}>set</button>
        </Form>
      );
    }
    render(<App />);
    expect(screen.queryByText('Server error')).not.toBe(null);
    fireEvent.click(screen.getByRole('button'));
    expect(screen.queryByText('Server error')).toBe(null);
  });

  it('G programmatic change resolves a visible validation error', () => {
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root data-testid="root" validationMode="onChange" validate={(v) => (v === 'bad' ? 'Bad' : null)}>
          <Field.Control value={value} onValueChange={setValue} />
          <Field.Error />
          <button type="button" onClick={() => setValue('good')}>set</button>
        </Field.Root>
      );
    }
    render(<App />);
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'bad' } });
    expect(screen.queryByText('Bad')).not.toBe(null);
    fireEvent.click(screen.getByRole('button'));
    expect(screen.queryByText('Bad')).toBe(null);
  });

  it('H controlled programmatic clear back to empty unsets filled/dirty', () => {
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root data-testid="root">
          <Field.Control value={value} onValueChange={setValue} />
          <button type="button" onClick={() => setValue('')}>clear</button>
        </Field.Root>
      );
    }
    render(<App />);
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'abc' } });
    const root = screen.getByTestId('root');
    expect(root.hasAttribute('data-filled')).toBe(true);
    fireEvent.click(screen.getByRole('button'));
    expect(root.hasAttribute('data-filled')).toBe(false);
    expect(root.hasAttribute('data-dirty')).toBe(false);
  });

  it('I controlled prefilled on mount is filled', () => {
    render(
      <Field.Root data-testid="root">
        <Field.Control value="foo" onValueChange={() => {}} />
      </Field.Root>,
    );
    expect(screen.getByTestId('root').hasAttribute('data-filled')).toBe(true);
  });

  it('J async validator for old value does not publish after programmatic change', async () => {
    let resolveOld: (v: string | null) => void = () => {};
    const validate = vi.fn((v: unknown) =>
      v === 'old' ? new Promise<string | null>((r) => { resolveOld = r; }) : null,
    );
    function App() {
      const [value, setValue] = React.useState('');
      return (
        <Field.Root validationMode="onChange" validate={validate}>
          <Field.Control value={value} onValueChange={setValue} />
          <Field.Error />
          <button type="button" onClick={() => setValue('new')}>set</button>
        </Field.Root>
      );
    }
    render(<App />);
    fireEvent.change(screen.getByRole('textbox'), { target: { value: 'old' } });
    fireEvent.click(screen.getByRole('button'));
    await act(async () => { resolveOld('Stale'); });
    expect(screen.queryByText('Stale')).toBe(null);
  });
});

